mapper.select:
select id,version,revision,project_id,scope,payload from capability_record
where bu_id=#{buId} and (project_id is null or project_id=#{projectId})
  and json_unquote(json_extract(payload,'$.status'))='已发布'
  and json_unquote(json_extract(payload,'$.modelId'))=#{modelId}
  and json_unquote(json_extract(payload,'$.metricCode'))=#{metricCode}
order by id,version desc
